/* From Uiverse.io by andrew-demchenk0 - Tags: blue, checkbox, transition, checkmark, box-shadow */
.__UIV_SCOPE__ .container {
  --input-focus: #2d8cf0;
  --input-out-of-focus: #ccc;
  --bg-color: #fff;
  --bg-color-alt: #666;
  --main-color: #323232;
  position: relative;
  cursor: pointer;
}

.__UIV_SCOPE__ .container input {
  position: absolute;
  opacity: 0;
}

.__UIV_SCOPE__ .checkmark {
  width: 30px;
  height: 30px;
  position: relative;
  top: 0;
  left: 0;
  border: 2px solid var(--main-color);
  border-radius: 5px;
  box-shadow: 4px 4px var(--main-color);
  background-color: var(--input-out-of-focus);
  transition: all 0.3s;
}

.__UIV_SCOPE__ .container input:checked ~ .checkmark {
  background-color: var(--input-focus);
}

.__UIV_SCOPE__ .checkmark:after {
  content: "";
  width: 7px;
  height: 15px;
  position: absolute;
  top: 2px;
  left: 8px;
  display: none;
  border: solid var(--bg-color);
  border-width: 0 2.5px 2.5px 0;
  transform: rotate(45deg);
}

.__UIV_SCOPE__ .container input:checked ~ .checkmark:after {
  display: block;
}
